@css:#pb_content .d_name,#pb_content .tail-info,#pb_content .p_content@html
<js>
lzs=source.getVariable()?source.getVariable():'';
lzb=book.getVariable("custom")?book.getVariable("custom"):'';
html=result.replace(/<\/span>\s*<li/g,'</span>◎🍵◎<li');
list=html.split('◎🍵◎')
h=""
for(i in list){
	java.setContent(list[i]);
	author=java.getString("@@class.d_name@text");	text=String(java.getString("@@class.d_post_content@html")).replace(/<a href="(.*?)".*?>.*?<\/a>/g,'$1').replace(/<img.*?(?:image_emoticon|face).*?>/g,'');
	l=java.getString("@@tag.span.-2@text");
	time=java.getString("@@tag.span.-1@text");	
if(String(lzs).match(/只看楼主/)||String(lzb).match(/只看楼主/)){
	h+=text+"\n"
	}else{	h+=author+"📜"+l+"⌚️"+time+"\n"+text+"\n&lrm;\n"
		}
	}
h
</js>
